use super::errors::*;
use nomina_fiscal_package::hashes;
use rusqlite::{Connection,OpenFlags};
use std::path::Path;
pub const SQL:&str=include_str!("migrations/001.sql");
pub const SQL2:&str=include_str!("migrations/002.sql");
pub const TABLES2:&[&str]=&["effective_admissions","fiscal_selections","selection_head"];
pub const TABLES:&[&str]=&["repository_meta","schema_migrations","operations","content_objects","signed_payloads","containers","trust_documents","trust_episodes","trust_episode_documents","trust_head","delegations","revoked_keys","withdrawn_payloads","signed_revision_floors","publications","publication_containers","verification_records","installations","admissions","accepted_heads","rollback_documents","selection_events","rollback_uses","recovery_events"];
pub fn open(path:&Path,readonly:bool)->Result<Connection>{super::paths::regular(path)?;if std::fs::metadata(path)?.len()>1_073_741_824{return Err(fail("DATABASE_LIMIT"));}let c=Connection::open_with_flags(path,if readonly{OpenFlags::SQLITE_OPEN_READ_ONLY}else{OpenFlags::SQLITE_OPEN_READ_WRITE})?;c.set_limit(rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,2_200_000)?;c.set_limit(rusqlite::limits::Limit::SQLITE_LIMIT_ATTACHED,0)?;c.busy_timeout(std::time::Duration::from_secs(5))?;c.execute_batch("PRAGMA foreign_keys=ON; PRAGMA trusted_schema=OFF; PRAGMA synchronous=FULL;")?;if !readonly{c.execute_batch("PRAGMA max_page_count=262144;")?;#[cfg(test)]super::tests::PAGES.with(|n|->Result<()>{if let Some(n)=n.get(){c.pragma_update(None,"max_page_count",n)?;}Ok(())})?;}Ok(c)}
pub fn version(c:&Connection)->Result<i64>{Ok(c.query_row("PRAGMA user_version",[],|r|r.get(0))?)}
pub fn create(c:&Connection)->Result<()>{create_at(c,2)}
pub fn create_at(c:&Connection,version:i64)->Result<()>{c.execute_batch(SQL)?;c.execute("INSERT INTO schema_migrations VALUES(1,?1)",[hashes::sha256(SQL.as_bytes())])?;if version==2{upgrade(c)?;}else if version!=1{return Err(fail("INCOMPATIBLE_SCHEMA"));}Ok(())}
pub fn upgrade(c:&Connection)->Result<()>{c.execute_batch(SQL2)?;c.execute("INSERT INTO schema_migrations VALUES(2,?1)",[hashes::sha256(SQL2.as_bytes())])?;Ok(())}
fn definition(c:&Connection)->Result<Vec<(String,String,String,Option<String>)>>{let mut s=c.prepare("SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY name")?;let rows=s.query_map([],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?)))?.collect::<rusqlite::Result<Vec<_>>>()?;Ok(rows)}
pub fn check(c:&Connection)->Result<()>{let version=version(c)?;let app:i64=c.query_row("PRAGMA application_id",[],|r|r.get(0))?;if ![1,2].contains(&version)||app!=1313230897{return Err(fail("INCOMPATIBLE_SCHEMA"));}let expected=Connection::open_in_memory()?;create_at(&expected,version)?;if definition(c)?!=definition(&expected)?{return Err(fail("INCOMPATIBLE_SCHEMA"));}let health:String=c.query_row("PRAGMA integrity_check",[],|r|r.get(0))?;if health!="ok"{return Err(fail("CORRUPT_DATABASE"));}if c.prepare("PRAGMA foreign_key_check")?.query([])?.next()?.is_some(){return Err(fail("CORRUPT_RECORD"));}Ok(())}
pub fn digest(c:&Connection)->Result<String>{let mut tables=TABLES.to_vec();if version(c)?==2{tables.extend_from_slice(TABLES2);}digest_tables(c,&tables)}
pub fn preserved(c:&Connection)->Result<String>{digest_tables(c,&TABLES.iter().copied().filter(|t|*t!="schema_migrations").collect::<Vec<_>>())}
fn digest_tables(c:&Connection,tables:&[&str])->Result<String>{use sha2::{Sha256,Digest};let mut h=Sha256::new();for table in tables{h.update(table.as_bytes());let s=c.prepare(&format!("SELECT * FROM {table}"))?;let cols=s.column_count();drop(s);let order=(1..=cols).map(|i|i.to_string()).collect::<Vec<_>>().join(",");let mut s=c.prepare(&format!("SELECT * FROM {table} ORDER BY {order}"))?;let mut rows=s.query([])?;while let Some(row)=rows.next()?{h.update([255]);for i in 0..cols{use rusqlite::types::ValueRef;let (kind,bytes)=match row.get_ref(i)?{ValueRef::Null=>(0,vec![]),ValueRef::Integer(n)=>(1,n.to_le_bytes().to_vec()),ValueRef::Text(b)=>(2,b.to_vec()),ValueRef::Blob(b)=>(3,b.to_vec()),ValueRef::Real(_)=>return Err(fail("CORRUPT_RECORD"))};h.update([kind]);h.update((bytes.len() as u64).to_le_bytes());h.update(bytes);}}}Ok(format!("{:x}",h.finalize()))}
